{"issue": true, "summary": "The `onAttemptFailure` function does not properly handle the case where `options.shouldConsumeRetry` returns false for a non-network TypeError, causing the retry logic to incorrectly proceed when it should abort.", "edits": [{"path": "index.js", "old": "	if (normalizedError instanceof TypeError && !isNetworkError(normalizedError)) {
		if (consumeRetry) {
			throw normalizedError;
		}

	options.signal?.throwIfAborted();
		return false;
	}", "new": "	if (normalizedError instanceof TypeError && !isNetworkError(normalizedError)) {
		if (consumeRetry) {
			throw normalizedError;
		}

		options.signal?.throwIfAborted();
		return false;
	}"}]}
